from random import getrandbits
def uint32_t(x): return x & 0xffffffff
def temper1(y,s):
    y = y ^ y >> s
    return uint32_t(y)
def temper2(y,d,s):
    y = y ^ ((y << s) & d)
    return uint32_t(y)

def untemper2(y,d,s):
    Y=list(map(int,bin(y)[2:].zfill(32)))
    d= d >> s
    for i in range(s+1,33):
        if d&1:
            Y[-i]=Y[-i] ^ Y[-i+s]
        d= d >> 1
    return int(''.join(map(str,Y)),2)

def untemper1(y,s):
    Y=list(map(int,bin(y)[2:].zfill(32)))
    for i in range(s,32):Y[i]=Y[i]^Y[i-s]
    return int(''.join(map(str,Y)),2)

n=uint32_t(getrandbits(32))
assert n==untemper1(temper1(n,18),18)
assert n==untemper2(temper2(n,0xEFC6FFFF,7),0xEFC6FFFF,7)
"""
y = y ^ y >> 11
    y = y ^ y << 7 & 2636928640
    y = y ^ y << 15 & 4022730752
    y = y ^ y >> 18
"""
def rasengan(y):
    y=untemper1(y,18)
    y=untemper2(y,4022730752,15)
    y=untemper2(y,2636928640,7)
    y=untemper1(y,11)

    return uint32_t(y) 
# cloner le mt19937 a partir de 7 sorties consecutives
state=[

829132121,4253810273,740421233,323826268,1935145039,144476726,2392598205
]

def rand():
    y = state[0]
    y = y ^ y >> 11
    y = y ^ y << 7 & 2636928640
    y = y ^ y << 15 & 4022730752
    y = y ^ y >> 18

    return uint32_t(y)

def twist():
    for i in range(7):
      y = uint32_t((state[i] & 0x80000000) + (state[(i + 1) % 7] & 0x7fffffff))
      state[i] = state[(i + 397) % 7] ^ y >> 1
      if y % 2 == 0: state[i] &= 0x9908b0df


for _ in range(7):
    state[_]=rasengan(state[_])
twist()
print(rand())

